UPDATE registration_schemas SET fields=(SELECT jsonb_agg(CASE WHEN item->>'key'='gender' THEN jsonb_set(item,'{options}','["Nam","Nữ"]'::jsonb) WHEN item->>'key'='clubSinceYear' THEN jsonb_set(item,'{label}',to_jsonb(CASE WHEN group_id='youth' THEN 'Tham gia Chúng thanh niên từ năm' ELSE 'Tham gia Đạo tràng từ năm' END)) ELSE item END ORDER BY ord) FROM jsonb_array_elements(fields) WITH ORDINALITY AS f(item,ord)),version=version+1 WHERE group_id IN ('youth','congregation') AND EXISTS (SELECT 1 FROM jsonb_array_elements(fields) item WHERE (item->>'key'='gender' AND item->'options' IS DISTINCT FROM '["Nam","Nữ"]'::jsonb) OR (item->>'key'='clubSinceYear' AND item->>'label' IS DISTINCT FROM CASE WHEN group_id='youth' THEN 'Tham gia Chúng thanh niên từ năm' ELSE 'Tham gia Đạo tràng từ năm' END));
